with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , GROSS_PREMIUM3 as TENURE_PREMIUM
        , 'BJAZ_EHH_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ehh_pol_dtls') }}
    where (nullif(trim(POLICY_REF),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TENURE_PREMIUM end) as TENURE_PREMIUM,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when TENURE_PREMIUM is not null
                     then md5(upper(coalesce(cast(TENURE_PREMIUM as varchar), '')))
                end as SAT_POLICY_TENURE_SCHEDULE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_TENURE_SCHEDULE_HASHDIFF is not null
